      "target": "",
      "args": {
        "code": "using UnityEngine;

public class SmoothYRotationMonoBehaviour : MonoBehaviour
{
    // Скорость вращения в градусах за секунду (30 градусов/сек)
    [SerializeField] private float rotationSpeedDegreesPerSecond = 30f;

    void Update()
    {
        // Преобразуем градусы в радианы для Transform.Rotate
        float radiansPerSecond = Mathf.Deg2Rad * rotationSpeedDegreesPerSecond;

        // Вращаем объект вокруг локальной оси Y (или глобальной, если нужно)
        // Используем Time.deltaTime для плавности и независимости от FPS
        transform.Rotate(0f, radiansPerSecond * Time.deltaTime, 0f);
    }
}",
        "description": "C# MonoBehaviour скрипт для вращения объекта вокруг оси Y со скоростью 30 градусов в секунду. Использует Update() и Time.deltaTime."
      }
    }
  ]
}

